<?php
/** Declarative invoice layouts: data only, never user-supplied HTML/CSS or PHP. */
function invoice_brand_keys(): array {return ['shop_name','shop_logo','shop_slogan','shop_email','shop_phone','shop_address','receipt_header','shop_phone_central','shop_phone_secondary','shop_phone_whatsapp','shop_address_central','shop_address_secondary','invoice_title','invoice_footer_note','invoice_thank_you','invoice_signature_shop_text','invoice_signature_cust_text','invoice_logo_position','invoice_watermark_opacity','invoice_watermark_size','invoice_accent_color','invoice_border_style','invoice_format','invoice_orientation','auto_print_invoice','invoice_show_phone_secondary','invoice_show_whatsapp','invoice_show_address_secondary','invoice_show_terms','invoice_show_signatures','invoice_show_barcode','invoice_watermark_enabled','invoice_layout'];}
function invoice_brand_key(string $key): bool {return in_array($key,invoice_brand_keys(),true)||str_starts_with($key,'invoice_')||str_starts_with($key,'shop_phone_')||str_starts_with($key,'shop_address_');}
function invoice_identity_keys(): array {return ['shop_name','shop_logo','shop_slogan','shop_email','shop_phone','shop_address','receipt_header','shop_phone_central','shop_phone_secondary','shop_phone_whatsapp','shop_address_central','shop_address_secondary','invoice_title','invoice_footer_note','invoice_thank_you','invoice_signature_shop_text','invoice_signature_cust_text'];}
function invoice_default_brand(): array {return ['shop_name'=>'','shop_logo'=>'','invoice_title'=>'','shop_slogan'=>'','shop_phone_central'=>'','shop_phone_secondary'=>'','shop_phone_whatsapp'=>'','shop_address_central'=>'','shop_address_secondary'=>'','invoice_footer_note'=>'','invoice_thank_you'=>'','invoice_signature_shop_text'=>'','invoice_signature_cust_text'=>'','invoice_logo_position'=>'right','invoice_watermark_opacity'=>'0.07','invoice_watermark_size'=>'medium','invoice_accent_color'=>'#294dc6','invoice_border_style'=>'modern','invoice_format'=>'a5','invoice_orientation'=>'portrait','auto_print_invoice'=>'0','invoice_show_phone_secondary'=>'1','invoice_show_whatsapp'=>'1','invoice_show_address_secondary'=>'1','invoice_show_terms'=>'1','invoice_show_signatures'=>'1','invoice_show_barcode'=>'1','invoice_watermark_enabled'=>'0'];}
function invoice_scope_settings(string $scope,int $id): array {
 global $pdo;if(!in_array($scope,['business','branch'],true)||$id<1)throw new InvalidArgumentException('Invalid invoice scope.');
 $table=$scope==='business'?'business_settings':'shop_settings';$col=$scope==='business'?'business_id':'shop_id';$q=$pdo->prepare("SELECT setting_key,setting_value FROM $table WHERE $col=?");$q->execute([$id]);return array_column($q->fetchAll(),'setting_value','setting_key');
}
function invoice_business_brand(int $business): array {
 global $pdo;$q=$pdo->prepare('SELECT name FROM businesses WHERE id=?');$q->execute([$business]);$name=$q->fetchColumn();if($name===false)throw new InvalidArgumentException('Business not found.');
 $defaults=invoice_default_brand();foreach($pdo->query('SELECT setting_key,setting_value FROM settings')->fetchAll() as $r)if(array_key_exists($r['setting_key'],$defaults)&&!in_array($r['setting_key'],invoice_identity_keys(),true))$defaults[$r['setting_key']]=$r['setting_value'];
 $defaults['shop_name']=$name;return array_replace($defaults,array_intersect_key(invoice_scope_settings('business',$business),array_flip(invoice_brand_keys())));
}
function invoice_effective_brand(int $branch): array {global $pdo;$q=$pdo->prepare('SELECT business_id FROM shops WHERE id=?');$q->execute([$branch]);$b=$q->fetchColumn();if(!$b)throw new InvalidArgumentException('Branch not found.');return array_replace(invoice_business_brand((int)$b),array_intersect_key(invoice_scope_settings('branch',$branch),array_flip(invoice_brand_keys())));}
function invoice_sections(): array {return ['header'=>['Business heading','مشخصات تجارت','د سوداګرۍ سرلیک'],'contact'=>['Contact details','تماس و آدرس','اړیکه او پته'],'customer'=>['Invoice and customer','بل و مشتری','بل او پیرودونکی'],'items'=>['Items','اجناس','توکي'],'totals'=>['Totals and payments','مجموع و پرداخت','ټول او تادیه'],'notes'=>['Terms and notes','شرایط و یادداشت','شرطونه او یادښت'],'signatures'=>['Signatures and QR','امضا و QR','لاسلیک او QR'],'footer'=>['Thank-you and footer','تشکری و پایین بل','مننه او د بل پای']];}
function invoice_sources(): array {return ['number'=>['No.','شماره','شمېره'],'product'=>['Product','جنس','توکی'],'specifications'=>['Specifications','مشخصات','ځانګړنې'],'quantity'=>['Quantity','مقدار','مقدار'],'unit_price'=>['Unit price','قیمت فی','د واحد بیه'],'total'=>['Total','مجموع','ټول'],'custom'=>['Custom field','خانهٔ دلخواه','ځانګړې خانه']];}
function invoice_default_layout(): array {return ['version'=>1,'sections'=>array_map(fn($id)=>['id'=>$id,'visible'=>true,'align'=>'start'],array_keys(invoice_sections())),'columns'=>array_map(fn($id)=>['id'=>$id,'source'=>$id,'labels'=>['en'=>'','da'=>'','ps'=>''],'width'=>(['product'=>4,'specifications'=>3,'quantity'=>2,'unit_price'=>3,'total'=>3][$id]??1),'required'=>false],['number','product','specifications','quantity','unit_price','total']),'blocks'=>[],'font_size'=>11,'spacing'=>'normal'];}
function invoice_plain($value,int $max=250): string {if(!is_string($value)||mb_strlen($value)>$max||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/',$value))throw new InvalidArgumentException(__t('Invalid or oversized invoice text.','نوشتهٔ بل نامعتبر یا بیش از حد دراز است.','د بل لیکنه ناسمه یا ډېره اوږده ده.'));return trim($value);}
function invoice_labels($value,int $max=80): array {if(!is_array($value)||array_diff(array_keys($value),['en','da','ps']))throw new InvalidArgumentException('Invalid language labels.');$out=[];foreach(['en','da','ps'] as $lang)$out[$lang]=invoice_plain($value[$lang]??'',$max);return $out;}
function invoice_layout_validate($data): array {
 if(!is_array($data)||($data['version']??null)!==1)throw new InvalidArgumentException('Invalid invoice layout version.');
 $out=['version'=>1,'sections'=>[],'columns'=>[],'blocks'=>[]];$sections=$data['sections']??null;$columns=$data['columns']??null;
 if(!is_array($sections)||count($sections)!==count(invoice_sections())||!is_array($columns)||count($columns)<4||count($columns)>12)throw new InvalidArgumentException(__t('Keep all layout sections and 4–12 columns.','تمام بخش‌های قالب و ۴ تا ۱۲ ستون را نگه دارید.','ټولې برخې او له ۴ تر ۱۲ ستنو وساتئ.'));
 $seen=[];foreach($sections as $s){$id=$s['id']??'';if(!is_string($id)||!isset(invoice_sections()[$id])||isset($seen[$id])||!is_bool($s['visible']??null)||!in_array($s['align']??'', ['start','center','end'],true))throw new InvalidArgumentException('Invalid layout section.');$seen[$id]=true;$out['sections'][]=['id'=>$id,'visible'=>in_array($id,['header','customer','items','totals'],true)||$s['visible'],'align'=>$s['align']];}
 $seen=[];$sources=[];$custom=0;foreach($columns as $c){$id=$c['id']??'';$source=$c['source']??'';if(!is_string($id)||!preg_match('/^[a-z][a-z0-9_]{0,31}$/D',$id)||isset($seen[$id])||!is_string($source)||!isset(invoice_sources()[$source])||!is_int($c['width']??null)||$c['width']<1||$c['width']>5||!is_bool($c['required']??null))throw new InvalidArgumentException('Invalid invoice column.');$seen[$id]=true;if($source==='custom'){if(++$custom>6)throw new InvalidArgumentException('At most 6 custom fields.');}elseif(isset($sources[$source]))throw new InvalidArgumentException('Duplicate invoice source.');$sources[$source]=true;$out['columns'][]=['id'=>$id,'source'=>$source,'labels'=>invoice_labels($c['labels']??[]),'width'=>$c['width'],'required'=>$source==='custom'&&$c['required']];}
 foreach(['product','quantity','unit_price','total'] as $source)if(!isset($sources[$source]))throw new InvalidArgumentException(__t('Product, quantity, unit price and total are required.','ستون جنس، مقدار، قیمت فی و مجموع ضروری است.','توکی، مقدار، د واحد بیه او ټول اړین دي.'));
 $blocks=$data['blocks']??[];if(!is_array($blocks)||count($blocks)>4)throw new InvalidArgumentException('At most 4 custom text blocks.');foreach($blocks as $b){$after=$b['after']??'';if(!isset(invoice_sections()[$after]))throw new InvalidArgumentException('Invalid text-block position.');$out['blocks'][]=['after'=>$after,'labels'=>invoice_labels($b['labels']??[],1000)];}
 $font=$data['font_size']??11;if(!is_int($font)||$font<9||$font>16||!in_array($data['spacing']??'',['compact','normal','relaxed'],true))throw new InvalidArgumentException('Invalid font or spacing.');$out['font_size']=$font;$out['spacing']=$data['spacing'];return $out;
}
function invoice_layout(array $brand): array {if(empty($brand['invoice_layout']))return invoice_default_layout();try{return invoice_layout_validate(json_decode($brand['invoice_layout'],true,32,JSON_THROW_ON_ERROR));}catch(Throwable $e){throw new RuntimeException(__t('The saved invoice layout is invalid. Ask central administration to repair it.','قالب ذخیره‌شدهٔ بل نامعتبر است؛ از مدیریت مرکزی اصلاح آن را بخواهید.','د بل ساتل شوې بڼه ناسمه ده؛ له مرکزي مدیر سمون وغواړئ.'));}}
function invoice_label(array $labels,string $fallback=''): string {return $labels[get_current_lang()]??$fallback ?: $fallback;}
function invoice_column_label(array $c): string {$own=invoice_label($c['labels']);return $own!==''?$own:($c['source']==='custom'?__t('Details','جزئیات','جزییات'):__t(...invoice_sources()[$c['source']]));}
function invoice_custom_values($values,array $layout): array {
 if(!is_array($values)||count($values)>6)throw new InvalidArgumentException('Invalid custom invoice values.');$allowed=[];foreach($layout['columns'] as $c)if($c['source']==='custom')$allowed[$c['id']]=$c;
 foreach($values as $key=>$v)if(!isset($allowed[$key]))throw new InvalidArgumentException('Unknown custom invoice field.');
 $out=[];foreach($allowed as $id=>$c){$out[$id]=invoice_plain($values[$id]??'',250);if($c['required']&&$out[$id]==='')throw new InvalidArgumentException(__t('Complete the required custom invoice fields.','خانه‌های ضروری دلخواه بل را خانه‌پُری کنید.','د بل اړینې ځانګړې خانې ډکې کړئ.'));}return $out;
}
function invoice_snapshot(int $branch): array {$brand=invoice_effective_brand($branch);return ['version'=>1,'brand'=>$brand,'layout'=>invoice_layout($brand)];}
function invoice_shared_design_keys(): array {return array_values(array_diff(invoice_brand_keys(),['shop_name','shop_email','shop_phone','shop_address','receipt_header','shop_phone_central','shop_phone_secondary','shop_phone_whatsapp','shop_address_central','shop_address_secondary']));}
function invoice_scope_revision(string $scope,int $id): string {$values=invoice_scope_settings($scope,$id);if($scope==='branch'){global $pdo;$q=$pdo->prepare('SELECT business_id FROM shops WHERE id=?');$q->execute([$id]);$parent=invoice_scope_settings('business',(int)$q->fetchColumn());ksort($parent);$values['_business_defaults']=$parent;}ksort($values);return hash('sha256',json_encode($values,JSON_THROW_ON_ERROR));}
function invoice_brand_validate(array $post,array $previous): array {
 $brand=$previous;$defaults=invoice_default_brand();$enums=['invoice_logo_position'=>['right','center','left','none'],'invoice_watermark_opacity'=>['0.04','0.07','0.12','0.18'],'invoice_watermark_size'=>['small','medium','large'],'invoice_border_style'=>['modern','classic','minimal'],'invoice_format'=>['a5','a4','thermal','doc'],'invoice_orientation'=>['portrait','landscape']];
 foreach($defaults as $key=>$default){if($key==='shop_logo'||!array_key_exists($key,$post))continue;$value=invoice_plain($post[$key],in_array($key,['invoice_footer_note','invoice_thank_you','shop_address_central','shop_address_secondary'],true)?2000:255);if(isset($enums[$key])&&!in_array($value,$enums[$key],true))throw new InvalidArgumentException('Invalid print option.');if($key==='invoice_accent_color'&&!preg_match('/^#[a-fA-F0-9]{6}$/D',$value))throw new InvalidArgumentException('Invalid invoice color.');if(($key==='auto_print_invoice'||str_starts_with($key,'invoice_show_')||$key==='invoice_watermark_enabled')&&!in_array($value,['0','1'],true))throw new InvalidArgumentException('Invalid invoice switch.');$brand[$key]=$value;}
 return $brand;
}
function invoice_scope_write(string $scope,int $id,string $key,string $value): void {
 global $pdo;if(!in_array($scope,['business','branch'],true)||!in_array($key,invoice_brand_keys(),true))throw new InvalidArgumentException('Invalid print setting.');$table=$scope==='business'?'business_settings':'shop_settings';$col=$scope==='business'?'business_id':'shop_id';$sql=$pdo->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite'?"INSERT INTO $table ($col,setting_key,setting_value) VALUES (?,?,?) ON CONFLICT($col,setting_key) DO UPDATE SET setting_value=excluded.setting_value,updated_at=CURRENT_TIMESTAMP":"INSERT INTO $table ($col,setting_key,setting_value) VALUES (?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=CURRENT_TIMESTAMP";$pdo->prepare($sql)->execute([$id,$key,$value]);unset($GLOBALS['_shop_settings_cache']);
}
/** Central access, CSRF, scope validation and optimistic revision checks apply to every save. */
function invoice_designer_save(array $post,array $files=[]): void {
 global $pdo;$actor=office2_actor();if(!csrf_verify($post['csrf_token']??''))throw new RuntimeException('Invalid form session.',403);
 $scope=$post['scope']??'';$id=filter_var($post['target_id']??null,FILTER_VALIDATE_INT);if(!in_array($scope,['business','branch'],true)||!$id||$id<1)throw new InvalidArgumentException('Choose a business or branch.');
 $table=$scope==='business'?'businesses':'shops';$q=$pdo->prepare("SELECT id FROM $table WHERE id=?");$q->execute([$id]);if(!$q->fetchColumn())throw new InvalidArgumentException('Invoice target not found.');
 $action=$post['designer_action']??'save';if(!in_array($action,['save','inherit'],true)||($action==='inherit'&&$scope!=='branch'))throw new InvalidArgumentException('Invalid designer action.');
 $all=($post['apply_all']??'0')==='1';if($all&&($scope!=='business'||($post['apply_confirmation']??'')!=='APPLY'))throw new InvalidArgumentException(__t('Type APPLY to replace existing branch designs.','برای تعویض دیزاین فعلی شعبه‌ها APPLY بنویسید.','د څانګو د بڼې بدلولو لپاره APPLY ولیکئ.'));
 $raw=$post['layout_json']??'';if($action==='save'&&(!is_string($raw)||strlen($raw)>65536||($post['designer_complete']??'')!=='1'))throw new InvalidArgumentException(__t('The design form was incomplete. Nothing saved.','فورم دیزاین ناقص رسید؛ چیزی ذخیره نشد.','د بڼې فورمه نیمګړې وه؛ څه نه دي ساتل شوي.'));
 $layout=$action==='save'?invoice_layout_validate(json_decode($raw,true,32,JSON_THROW_ON_ERROR)):null;$newLogo=null;
 $pdo->beginTransaction();try{
  $pdo->exec("UPDATE settings SET setting_value=setting_value WHERE setting_key='shop_name'");
  if(!is_string($post['revision']??null)||!hash_equals(invoice_scope_revision($scope,$id),$post['revision']))throw new RuntimeException(__t('Another edit changed these settings. Refresh before saving.','تنظیمات در جای دیگر تغییر کرده؛ پیش از ذخیره صفحه را تازه کنید.','تنظیمات بدل شوي؛ پاڼه تازه کړئ.'),409);
  if($action==='inherit'){$keys=invoice_shared_design_keys();$marks=implode(',',array_fill(0,count($keys),'?'));$pdo->prepare("DELETE FROM shop_settings WHERE shop_id=? AND setting_key IN ($marks)")->execute([$id,...$keys]);}
  else{
   $previous=$scope==='business'?invoice_business_brand($id):invoice_effective_brand($id);$brand=invoice_brand_validate($post,$previous);
   if(isset($files['shop_logo'])&&($files['shop_logo']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$path=office2_shop_logo_upload($id,$files['shop_logo']);if($path!==''){$brand['shop_logo']=$path;$newLogo=BASE_DIR.'/uploads/'.$path;}}
   if(($post['remove_logo']??'0')==='1')$brand['shop_logo']='';
   $brand['invoice_layout']=json_encode($layout,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
   $base=$scope==='branch'?invoice_business_brand((int)domain_branch($id)['business_id']):[];
   if($scope==='branch')$base['invoice_layout']=json_encode(invoice_layout($base),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
   foreach($brand as $key=>$value)if(in_array($key,invoice_brand_keys(),true)){
    if($scope==='branch'&&array_key_exists($key,$base)&&(string)$base[$key]===(string)$value)$pdo->prepare('DELETE FROM shop_settings WHERE shop_id=? AND setting_key=?')->execute([$id,$key]);
    else invoice_scope_write($scope,$id,$key,(string)$value);
   }
   if($all){$keys=invoice_shared_design_keys();$marks=implode(',',array_fill(0,count($keys),'?'));$pdo->prepare("DELETE FROM shop_settings WHERE shop_id IN (SELECT id FROM shops WHERE business_id=?) AND setting_key IN ($marks)")->execute([$id,...$keys]);}
  }
  domain_audit('invoice_design_saved',$scope,$id,['apply_to_branches'=>$all,'inherit'=>$action==='inherit'],(int)$actor['id']);$pdo->commit();unset($GLOBALS['_shop_settings_cache']);
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($newLogo&&is_file($newLogo))unlink($newLogo);throw $e;}
}
